import { ReactFlowProvider } from 'reactflow';
import { PipelineToolbar } from './toolbar';
import { PipelineUI }      from './ui';
import { SubmitButton }    from './submit';
import { Zap } from 'lucide-react';

function App() {
  return (
    <ReactFlowProvider>
      <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', background: '#0a0a0f', overflow: 'hidden' }}>

        {/* Top bar */}
        <div style={{
          height: 48,
          padding: '0 20px',
          background: '#111118',
          borderBottom: '1px solid #1e1e2a',
          display: 'flex',
          alignItems: 'center',
          gap: 10,
          flexShrink: 0,
        }}>
          <span style={{ color: '#6366f1', display: 'flex' }}>
            <Zap size={16} strokeWidth={2.5} fill="#6366f1" />
          </span>
          <span style={{
            color: '#e8e8f0',
            fontWeight: 700,
            fontSize: 14,
            letterSpacing: 0.2,
            fontFamily: "'Inter', system-ui, sans-serif",
          }}>
            VectorShift
          </span>
          <span style={{
            color: '#2a2a3a',
            fontSize: 14,
            fontWeight: 300,
          }}>|</span>
          <span style={{ color: '#55556a', fontSize: 13, fontFamily: "'Inter', system-ui, sans-serif" }}>
            Pipeline Builder
          </span>
        </div>

        <PipelineToolbar />

        {/* Canvas */}
        <div style={{ flex: 1, overflow: 'hidden' }}>
          <PipelineUI />
        </div>

        <SubmitButton />
      </div>
    </ReactFlowProvider>
  );
}

export default App;
